"use client";

import { useCallback, useEffect, useState } from "react";
import styles from "./page.module.css";

type SupportButtonProps = {
  slug: string;
  seed: number;
  delivery: string;
  goal: number;
  compact?: boolean;
};

type SupportUpdatedDetail = { slug: string; count: number };
const SUPPORT_EVENT = "2100-support-updated";

async function readCount(slug: string) {
  const response = await fetch(`/api/2100/support?slug=${encodeURIComponent(slug)}`, {
    cache: "no-store",
  });
  if (!response.ok) throw new Error("failed to read support count");
  const data = (await response.json()) as { count: number };
  return data.count;
}

export function SupportCount({ slug, seed }: { slug: string; seed: number }) {
  const [count, setCount] = useState(seed);

  useEffect(() => {
    let active = true;
    readCount(slug)
      .then((value) => {
        if (active) setCount(value);
      })
      .catch(() => undefined);

    const sync = (event: Event) => {
      const detail = (event as CustomEvent<SupportUpdatedDetail>).detail;
      if (detail?.slug === slug) setCount(detail.count);
    };
    window.addEventListener(SUPPORT_EVENT, sync);

    return () => {
      active = false;
      window.removeEventListener(SUPPORT_EVENT, sync);
    };
  }, [slug]);

  return <>{count.toLocaleString("ja-JP")}</>;
}

export default function SupportButton({
  slug,
  seed,
  delivery,
  goal,
  compact = false,
}: SupportButtonProps) {
  const storageKey = `2100-backed:${slug}`;
  const [count, setCount] = useState(seed);
  const [backed, setBacked] = useState(false);
  const [loading, setLoading] = useState(false);
  const [messageOpen, setMessageOpen] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    setBacked(window.localStorage.getItem(storageKey) === "1");
    let active = true;
    readCount(slug)
      .then((value) => {
        if (active) setCount(value);
      })
      .catch(() => undefined);

    const sync = (event: Event) => {
      const detail = (event as CustomEvent<SupportUpdatedDetail>).detail;
      if (detail?.slug !== slug) return;
      setCount(detail.count);
      setBacked(true);
    };
    window.addEventListener(SUPPORT_EVENT, sync);

    return () => {
      active = false;
      window.removeEventListener(SUPPORT_EVENT, sync);
    };
  }, [slug, storageKey]);

  const support = useCallback(async () => {
    if (window.localStorage.getItem(storageKey) === "1") {
      setBacked(true);
      setMessageOpen(true);
      return;
    }

    setLoading(true);
    setError("");
    try {
      const response = await fetch("/api/2100/support", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ slug }),
      });
      if (!response.ok) throw new Error("failed to support");
      const data = (await response.json()) as { count: number };
      window.localStorage.setItem(storageKey, "1");
      setCount(data.count);
      setBacked(true);
      window.dispatchEvent(
        new CustomEvent<SupportUpdatedDetail>(SUPPORT_EVENT, {
          detail: { slug, count: data.count },
        }),
      );
      setMessageOpen(true);
    } catch {
      setError("未来との通信に失敗しました。もう一度お試しください。");
    } finally {
      setLoading(false);
    }
  }, [slug, storageKey]);

  const progress = Math.max(0, Math.round((count / goal) * 100));

  return (
    <div className={compact ? styles.supportCompact : styles.supportBox}>
      <div className={styles.supportStats}>
        <div>
          <strong>{count.toLocaleString("ja-JP")}</strong>
          <span>未来の支援者</span>
        </div>
        <div>
          <strong>{progress}%</strong>
          <span>目標達成</span>
        </div>
        <div>
          <strong>{delivery}</strong>
          <span>未来の出荷予定</span>
        </div>
      </div>

      <div className={styles.progressTrack} aria-label={`目標達成率 ${progress}%`}>
        <span style={{ width: `${Math.min(progress, 100)}%` }} />
      </div>

      <button
        className={backed ? styles.supportedButton : styles.supportButton}
        type="button"
        onClick={support}
        disabled={loading}
      >
        {loading ? "未来へ送信中…" : backed ? "✓ この未来を支援済み" : "この未来を支援する"}
      </button>
      <p className={styles.freeNote}>¥0 ・ 登録不要 ・ 決済なし</p>
      {error && <p className={styles.supportError}>{error}</p>}

      {messageOpen && (
        <div className={styles.backdrop} role="presentation" onClick={() => setMessageOpen(false)}>
          <div
            className={styles.supportModal}
            role="dialog"
            aria-modal="true"
            aria-labelledby="support-complete-title"
            onClick={(event) => event.stopPropagation()}
          >
            <span className={styles.modalSignal}>FUTURE BACKED</span>
            <h2 id="support-complete-title">支援の気持ちを受け取りました。</h2>
            <p>
              あなたは、この未来を待つ
              <br />
              <strong>{count.toLocaleString("ja-JP")}人</strong>のひとりです。
            </p>
            <div className={styles.modalDelivery}>
              <span>FUTURE DELIVERY</span>
              <b>{delivery}</b>
            </div>
            <p className={styles.modalJoke}>気長にお待ちください。</p>
            <p className={styles.modalDisclaimer}>
              ※これはフィクション型コンテンツです。実際の注文・決済・商品発送は発生していません。
            </p>
            <button type="button" onClick={() => setMessageOpen(false)}>
              未来へ戻る
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import type { ReactNode } from "react";

export default function ProjectVisualLayout({ children }: { children: ReactNode }) {
  return (
    <>
      {children}
      <style>{`
        [class*="sectionNav"] {
          overflow-x: auto;
          justify-content: flex-start !important;
          white-space: nowrap;
          -webkit-overflow-scrolling: touch;
          scrollbar-width: none;
        }
        [class*="sectionNav"]::-webkit-scrollbar {
          display: none;
        }
        [class*="sectionNav"] a {
          flex: 0 0 auto;
          white-space: nowrap;
          word-break: keep-all;
        }
      `}</style>
    </>
  );
}

.page {
  --blue: #1167e8;
  --navy: #082548;
  --ink: #0d294d;
  --muted: #64758b;
  --line: #dbe7f4;
  --paper: #f8fbff;
  min-height: 100vh;
  overflow-x: hidden;
  background: #fff;
  color: var(--ink);
  font-family: Inter, "Noto Sans JP", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.page *, .page *::before, .page *::after { box-sizing: border-box; }
.page img { display: block; width: 100%; max-width: 100%; }
.page figure { margin: 0; }

.fictionBar {
  display: flex;
  gap: 18px;
  align-items: center;
  padding: 12px max(24px, calc((100vw - 1180px) / 2));
  background: #061f3e;
  color: #e8f3ff;
  font-size: 13px;
  line-height: 1.6;
}
.fictionBar strong { color: #74b2ff; letter-spacing: .16em; white-space: nowrap; }

.header {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
  padding: 26px 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.logo { color: var(--ink); text-decoration: none; font-size: 28px; font-weight: 850; letter-spacing: .02em; }
.logo b { color: var(--blue); }
.logo small { display: block; margin-top: 4px; font-size: 11px; font-weight: 650; letter-spacing: .04em; color: #5e7189; }
.headerNav { display: flex; align-items: center; gap: 22px; font-size: 13px; font-weight: 700; }
.headerNav a { color: #314a67; text-decoration: none; white-space: nowrap; }

.hero {
  width: min(1180px, calc(100% - 48px));
  margin: 8px auto 36px;
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  gap: clamp(28px, 5vw, 70px);
  align-items: center;
}
