.eyebrow, .sectionKicker { margin: 0 0 12px; color: var(--blue); font-size: 12px; font-weight: 900; letter-spacing: .18em; }
.hero h1 { margin: 0; font-size: clamp(46px, 5.2vw, 76px); line-height: 1.05; letter-spacing: -.045em; }
.productName { margin: 20px 0 8px; font-size: 23px; font-weight: 900; letter-spacing: .05em; }
