.heroMiniStats div:last-child { border-right: 0; }
.heroMiniStats small { display: block; margin-bottom: 5px; color: #75869b; font-size: 10px; }
.heroMiniStats strong { display: block; font-size: 14px; white-space: nowrap; }
.supportWrap { margin-top: 12px; }
.heroNote { margin: 8px 0 0; color: #7a899b; font-size: 11px; }
.heroVisual { position: relative; overflow: hidden; min-height: 520px; border-radius: 30px; background: #eaf3ff; box-shadow: 0 26px 70px rgba(8, 49, 96, .16); }
.heroVisual img { width: 100%; height: 100%; min-height: 520px; object-fit: cover; object-position: center; }
.heroVisual figcaption { position: absolute; left: 22px; bottom: 22px; padding: 13px 16px; border-radius: 14px; background: rgba(255,255,255,.92); backdrop-filter: blur(12px); }
