.gravityPanel { position: relative; width: min(1180px, calc(100% - 32px)); min-height: 540px; margin: 40px auto; overflow: hidden; border-radius: 30px; color: #fff; }
.gravityPanel > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.gravityOverlay { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(3,16,34,.9) 0%, rgba(3,16,34,.56) 48%, rgba(3,16,34,.18) 100%); }
.gravityContent { position: relative; z-index: 2; max-width: 660px; padding: 74px 62px; }
.gravityContent h2 { margin: 0 0 32px; max-width: 620px; font-size: clamp(38px, 5vw, 62px); line-height: 1.12; letter-spacing: -.035em; }
.problemPoints { display: flex; flex-wrap: wrap; gap: 10px; }
.problemPoints span { padding: 11px 14px; border: 1px solid rgba(255,255,255,.25); border-radius: 999px; background: rgba(7,30,57,.55); font-size: 13px; backdrop-filter: blur(10px); }
