.researchGrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.researchCard { padding: 26px; border: 1px solid var(--line); border-radius: 22px; background: #fff; }
.donut { width: 116px; height: 116px; margin-bottom: 18px; display: grid; place-items: center; border-radius: 50%; background: conic-gradient(var(--blue) 0 76%, #e7f0fa 76%); position: relative; }
.donut::after { content: ""; position: absolute; inset: 13px; border-radius: 50%; background: #fff; }
.donut span { position: relative; z-index: 1; color: var(--blue); font-size: 25px; font-weight: 900; }
.researchCard p { margin: 0; font-weight: 750; line-height: 1.6; }
.fakeNote { display: block; margin-top: 14px; color: #7c8a9d; }

.solutionBadge { margin-top: 22px; display: inline-flex; padding: 9px 12px; border-radius: 9px; background: #eaf3ff; color: var(--blue); font-size: 11px; font-weight: 900; letter-spacing: .08em; }

.storySection { padding-top: 92px; }
.sketchFeature { display: grid; grid-template-columns: 1.25fr .75fr; overflow: hidden; margin-bottom: 30px; border: 1px solid #dfebf7; border-radius: 28px; background: #f6f1e8; box-shadow: 0 20px 55px rgba(53, 46, 33, .1); }
.sketchFeature img { width: 100%; height: 100%; min-height: 430px; object-fit: cover; }
.sketchFeature figcaption { padding: 42px 34px; align-self: center; }
.sketchFeature figcaption span { display: block; margin-bottom: 10px; color: var(--blue); font-size: 11px; font-weight: 900; letter-spacing: .14em; }
.sketchFeature figcaption b { display: block; font-size: 27px; line-height: 1.4; }
.sketchFeature figcaption p { margin: 14px 0 0; color: #64748a; line-height: 1.8; }
.storyGrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.storyCard { overflow: hidden; position: relative; padding: 0 18px 22px; border: 1px solid var(--line); border-radius: 20px; background: #fff; }
