.journeyStep h3 { margin: 6px 0; }
.journeyStep p { margin: 0; color: #65768a; font-size: 12px; line-height: 1.6; }

.compareSection { padding-top: 92px; }
.compareGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.comparePhoto { position: relative; overflow: hidden; min-height: 450px; border-radius: 26px; background: #14263c; color: #fff; }
.comparePhoto > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; filter: brightness(.55); }
.compareAfter > img { filter: brightness(.88); }
.comparePhoto > div { position: absolute; z-index: 2; left: 28px; right: 28px; bottom: 28px; }
