.beliefSection { padding-top: 92px; }
.developerCard { display: grid; grid-template-columns: .9fr 1.1fr; overflow: hidden; border-radius: 28px; background: #eef5fc; }
.developerPhoto { min-height: 430px; overflow: hidden; }
.developerPhoto img { width: 100%; height: 100%; min-height: 430px; object-fit: cover; object-position: 84% center; }
.developerCard > div:last-child { padding: 52px 46px; align-self: center; }
.developerCard blockquote { margin: 10px 0 24px; font-size: clamp(27px, 3vw, 40px); font-weight: 850; line-height: 1.45; letter-spacing: -.02em; }
.developerCard strong, .developerCard small { display: block; }
