.rewardSection { padding-top: 92px; }
.rewardGrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.rewardCard { position: relative; padding: 28px; border: 1px solid var(--line); border-radius: 22px; background: #fff; }
.rewardFeatured { border: 2px solid var(--blue); background: #f5f9ff; }
.rewardBadge { position: absolute; top: 14px; right: 14px; padding: 5px 8px; border-radius: 999px; background: #ffbf23; color: #4b3500; font-size: 9px; font-weight: 900; }
.rewardCard h3 { margin: 0 0 10px; }
.rewardCard > strong { display: block; margin-bottom: 10px; font-size: 28px; }
.rewardCard p { color: #64768a; line-height: 1.7; }
.rewardCard a { display: inline-flex; margin-top: 6px; color: var(--blue); font-weight: 850; text-decoration: none; }
.rewardSupport { max-width: 760px; margin: 26px auto 0; }

.scheduleSection { padding-top: 92px; }
.scheduleTrack { position: relative; display: grid; grid-template-columns: repeat(6, 1fr); gap: 0; }
.scheduleTrack::before { content: ""; position: absolute; top: 20px; left: 8%; right: 8%; height: 2px; background: #d8e6f5; }
.scheduleItem { position: relative; z-index: 1; text-align: center; }
.scheduleItem span { width: 40px; height: 40px; margin: 0 auto 10px; display: grid; place-items: center; border: 2px solid #b8d2ef; border-radius: 50%; background: #fff; color: var(--blue); font-weight: 900; }
.scheduleItem b, .scheduleItem small { display: block; }
.scheduleItem b { font-size: 13px; }
.scheduleItem small { margin-top: 4px; color: #6b7b90; font-size: 10px; }

.faqSection { padding-top: 92px; }
.faqList { border-top: 1px solid var(--line); }
.faqItem { border-bottom: 1px solid var(--line); }
.faqItem summary { padding: 20px 4px; cursor: pointer; font-weight: 800; list-style: none; }
.faqItem summary::-webkit-details-marker { display: none; }
.faqItem summary span, .faqItem p span { margin-right: 10px; color: var(--blue); font-weight: 900; }
