  .sketchFeature img { min-height: 0; aspect-ratio: 4 / 3; }
  .sketchFeature figcaption { padding: 24px 20px; }
  .storyGrid { grid-template-columns: 1fr 1fr; gap: 10px; }
  .storyCard { padding: 0 14px 18px; }
  .storyPhoto { margin: 0 -14px 14px; height: 120px; }
  .techSection { padding: 58px 16px; }
  .techStage { min-height: 380px; border-radius: 20px; }
  .techStage > img { height: 380px; }
  .techPins span { font-size: 10px; padding: 8px 10px; }
  .techGrid { grid-template-columns: 1fr; }
  .gimmickGrid { grid-template-columns: 1fr 1fr; gap: 10px; }
  .gimmickCard { padding: 0 12px 15px; }
  .gimmickImage { margin: 0 -12px 12px; height: 120px; }
  .journeyTrack { grid-template-columns: 1fr; }
  .journeyStep:last-child { grid-column: auto; }
  .journeyStep { display: grid; grid-template-columns: 42% 1fr; grid-template-rows: auto auto 1fr; gap: 0 14px; padding: 0; min-height: 190px; }
  .journeyImage { grid-row: 1 / 4; width: 100%; height: 100%; min-height: 190px; margin: 0; }
