  .donut { width: 70px; height: 70px; }
  .scheduleTrack { grid-template-columns: 1fr; }
  .scheduleItem { display: grid; grid-template-columns: 44px 76px 1fr; align-items: center; text-align: left; gap: 8px; }
  .scheduleItem span { margin: 0; }
  .scheduleItem small { margin: 0; }
