.featuredPhoto {
  position: absolute;
  inset: 0;
  margin: 0;
  background: #d9d9d9;
}

.featuredPhoto::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,.02) 45%, rgba(0,0,0,.28) 100%);
  pointer-events: none;
}

.featuredPhoto img {
  width: 100%;
  height: 100%;
  min-height: 670px;
  display: block;
  object-fit: cover;
}

.productGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 28px 20px;
}

.productCard {
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #fff;
  border: 1px solid rgba(18,18,18,.14);
  border-radius: 10px;
  color: inherit;
  text-decoration: none;
  box-shadow: 0 1px 0 rgba(18,18,18,.05);
  transition: transform .18s ease, box-shadow .18s ease;
}

a.productCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 14px 32px rgba(18,18,18,.13);
}

.disabledCard {
  opacity: .92;
}

.photoFrame {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: #ddd;
}

.photoFrame img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform .35s ease;
}

a.productCard:hover .photoFrame img {
  transform: scale(1.025);
}

.deliveryBadge,
.comingSoonBadge {
  position: absolute;
  z-index: 2;
  padding: 7px 9px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .08em;
  line-height: 1;
}

.deliveryBadge {
  left: 12px;
  bottom: 12px;
  background: rgba(255,255,255,.94);
  color: #111;
}

.comingSoonBadge {
  top: 12px;
  right: 12px;
  background: #111;
  color: #fff;
}

.productCardBody {
  padding: 17px 17px 18px;
  display: flex;
  flex: 1;
  flex-direction: column;
}

.cardMeta {
  margin: 0 0 9px;
  color: #777;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .08em;
}

.productCardBody h3 {
  margin: 0;
  font-size: 21px;
  line-height: 1.32;
  letter-spacing: -.035em;
}

.tagline {
  margin: 10px 0 18px;
  color: #4a4a4a;
  font-size: 13px;
  line-height: 1.65;
  font-weight: 700;
}

.progressTrack {
  height: 4px;
  margin-top: auto;
  overflow: hidden;
  background: #e9e9e9;
  border-radius: 999px;
}

.progressFill,
.progressFillMuted {
