}

.progressFill {
  width: 6%;
  min-width: 12px;
  background: #ff5b4d;
}

.progressFillMuted {
  width: 100%;
  background: #cfcfcf;
}

.cardStats {
  margin-top: 11px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  font-size: 10px;
}

