.page {
  --ink: #121212;
  --paper: #f4f1e8;
  --acid: #d8ff3e;
  --signal: #ff5b4d;
  --blue: #76b9ff;
  min-height: 100vh;
  background: var(--paper);
  color: var(--ink);
  font-family: Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
}

.page *, .page *::before, .page *::after { box-sizing: border-box; }
.page a { color: inherit; }

.fictionBar {
  min-height: 38px;
