  border-bottom: 1px solid var(--ink);
  background:
    linear-gradient(90deg, transparent 49.8%, rgba(18,18,18,.06) 50%, transparent 50.2%),
    linear-gradient(rgba(18,18,18,.05) 1px, transparent 1px),
