.gravityLineOne, .gravityLineTwo, .gravityLineThree { position: absolute; left: 12%; height: 3px; background: var(--ink); transform-origin: left; }
.gravityLineOne { width: 170px; top: 36%; transform: rotate(-12deg); }
.gravityLineTwo { width: 120px; top: 43%; transform: rotate(-5deg); }
.gravityLineThree { width: 210px; top: 50%; transform: rotate(5deg); }

.featuredCopy {
  padding: 68px 6vw;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: #fffdf7;
}
.projectMeta { margin: 0 0 16px; font-size: 10px; font-weight: 900; letter-spacing: .13em; color: #666; }
.featuredCopy h2 { margin: 0; font-size: clamp(42px, 5vw, 72px); line-height: 1; letter-spacing: -.065em; }
.featuredTagline { margin: 22px 0 15px; font-size: 24px; line-height: 1.45; font-weight: 900; }
.featuredTeaser { margin: 0; max-width: 600px; font-size: 15px; line-height: 1.9; color: #454545; }
.featuredNumbers { margin: 36px 0 28px; display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--ink); border-bottom: 1px solid var(--ink); }
.featuredNumbers div { padding: 18px 0; }
.featuredNumbers div + div { padding-left: 22px; border-left: 1px solid var(--ink); }
.featuredNumbers strong, .featuredNumbers span { display: block; }
.featuredNumbers strong { font-size: 27px; letter-spacing: -.05em; }
.featuredNumbers span { margin-top: 5px; font-size: 9px; font-weight: 900; letter-spacing: .14em; }
.primaryCta {
  width: 100%;
  min-height: 60px;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--ink);
  color: white !important;
  text-decoration: none;
  font-weight: 900;
}
.primaryCta span { color: var(--acid); font-size: 24px; }

.projectsSection, .trendingSection, .eraSection, .nextFuture { padding: 88px 6vw; border-bottom: 1px solid var(--ink); }
.sectionTitle { margin-bottom: 34px; display: flex; align-items: end; justify-content: space-between; gap: 20px; }
.sectionTitle h2 { margin: 8px 0 0; font-size: clamp(38px, 5vw, 68px); line-height: 1; letter-spacing: -.06em; }
.sectionTitle > span { font-size: 11px; font-weight: 800; }
.projectGrid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.projectCard { min-width: 0; display: flex; flex-direction: column; border: 1px solid var(--ink); background: #fffdf7; text-decoration: none; transition: transform .15s ease, box-shadow .15s ease; }
a.projectCard:hover { transform: translateY(-4px); box-shadow: 8px 8px 0 var(--ink); }
.disabledCard { opacity: .83; }
.projectArt { position: relative; height: 230px; padding: 18px; display: grid; place-items: center; border-bottom: 1px solid var(--ink); overflow: hidden; }
.projectArt::after { content: ""; position: absolute; width: 210px; height: 210px; border: 1px solid rgba(18,18,18,.2); border-radius: 50%; transform: translate(35%, -35%); }
.yellow { background: #d8ff3e; } .blue { background: #76b9ff; } .pink { background: #ff9ab5; } .green { background: #8ef1a5; } .violet { background: #b8a4ff; } .orange { background: #ffb45f; }
