.trendingList > li > span { color: var(--acid); font-size: 28px; font-weight: 900; }
.trendingList div { display: flex; gap: 24px; align-items: baseline; }
.trendingList b { font-size: 20px; }
.trendingList small { color: #aaa; }
.trendingList strong { font-size: 16px; color: var(--acid); }

.eraSection { background: #e9e5da; }
