.storyNav { position: sticky; z-index: 10; top: 0; min-height: 48px; padding: 0 5vw; display: flex; align-items: center; justify-content: center; gap: 34px; border-bottom: 1px solid var(--ink); background: rgba(244,241,232,.96); backdrop-filter: blur(8px); }
