  .featuredCopy, .projectHeroCopy { padding: 46px 20px; }
  .featuredTagline, .projectTagline { font-size: 21px; }
  .bagScene { min-height: 470px; }
  .bagSceneLarge, .projectHeroVisual { min-height: 560px; }
  .bagBody { width: 68%; }
  .bagBodyLarge { width: 72%; padding: 26px; }
  .bagHandleLarge { width: 160px; height: 120px; border-width: 26px; }
  .bagBodyLarge span { font-size: 86px; }
  .bagBodyLarge i { font-size: 34px; }
  .projectGrid { grid-template-columns: 1fr; }
  .projectsSection, .trendingSection, .eraSection, .nextFuture { padding: 62px 20px; }
  .sectionTitle { align-items: start; flex-direction: column; }
  .sectionTitle h2 { font-size: 43px; }
  .trendingList li { grid-template-columns: 44px 1fr; padding: 18px 0; }
  .trendingList li > strong { grid-column: 2; }
  .eraGrid { grid-template-columns: 1fr 1fr; }
  .eraGrid div:nth-child(3) { border-left: 0; border-top: 1px solid var(--ink); }
  .eraGrid div:nth-child(4) { border-top: 1px solid var(--ink); }
  .about2100 { padding: 70px 20px; }
  .about2100 > div { grid-template-columns: 1fr; gap: 25px; }
  .footer { min-height: 130px; padding: 24px 20px; grid-template-columns: 1fr; gap: 13px; }
  .footer small { justify-self: start; }
  .supportStats { grid-template-columns: 1fr 1fr; }
  .supportStats > div:nth-child(3) { grid-column: 1 / 3; border-left: 0; border-top: 1px solid var(--ink); padding-left: 0; }
  .storyNav { overflow-x: auto; justify-content: flex-start; gap: 20px; padding: 0 16px; }
  .storyChapter { grid-template-columns: 1fr; }
  .yearColumn { min-height: 100px; padding: 20px; flex-direction: row; align-items: end; border-right: 0; border-bottom: 1px solid var(--ink); }
  .yearColumn small { writing-mode: horizontal-tb; }
  .storyBody { padding: 56px 20px 68px; }
  .storyBody h2 { font-size: 45px; }
  .storyLead { font-size: 16px; }
  .weightCompare { grid-template-columns: 1fr; }
  .weightCompare div + div { border-left: 0; border-top: 1px solid var(--ink); }
  .weekChart { height: 290px; gap: 6px; padding: 20px 10px; }
  .failureTimeline, .featuresGrid { grid-template-columns: 1fr; }
  .failureTimeline div:nth-child(even), .featuresGrid div:nth-child(even) { border-left: 0; }
  .failureTimeline div + div, .featuresGrid div + div { border-top: 1px solid var(--ink); }
  .lifeMoments div { grid-template-columns: 85px 1fr; }
  .lifeMoments p { font-size: 16px; }
  .whyStatement { padding: 25px; }
  .whyStatement strong { font-size: 30px; }
  .roadmapSection, .updatesSection, .faqSection, .finalSupport { padding: 68px 20px; }
  .roadmap { grid-template-columns: 1fr 1fr; }
  .roadmap div:nth-child(odd) { border-left: 0; }
  .roadmap div:nth-child(n+3) { border-top: 1px solid var(--ink); }
  .updateList article { grid-template-columns: 1fr; gap: 9px; }
  .teamSection { padding: 64px 20px; grid-template-columns: 1fr; }
  .teamSection blockquote { font-size: 20px; }
  .supportModal { padding: 26px 20px; }
}

